161	/**
162	 * @brief Reduce a u320_t modulo 2^130 - 5
163	 *
164	 * @param a Value to reduce
165	 */
166	u320_t uint320_mod_prime(u320_t a)
167	{
168	    // First, handle the high bits (greater than or equal to 2^130)
169	    uint64_t mask = 0x3FFFFFFFFFF; // 2^130 - 1
170	    uint64_t high_bits = a.limbs[2] & ~mask;
171	    if (high_bits || a.limbs[3] || a.limbs[4])
172	    {
173	        // We have bits above 2^130, need to reduce
174	
175	        // Clear high bits
176	        a.limbs[2] &= mask;
177	        a.limbs[3] = 0;
178	        a.limbs[4] = 0;
179	
180	        // Multiply high bits by 5 and add to low bits
181	        u320_t mul5 = {0};
182	
183	        // high_bits * 5
184	        mul5.limbs[0] = (high_bits >> 2) * 5;
185	
186	        // Add to original value
187	        a = uint320_add(a, mul5);
188	    }
189	
190	    // Check if result is still >= 2^130 - 5
191	    if ((a.limbs[2] & mask) == mask &&
192	        a.limbs[1] == 0xFFFFFFFFFFFFFFFF &&
193	        a.limbs[0] >= 0xFFFFFFFFFFFFFFFB)
194	    {
195	
196	        // Subtract 2^130 - 5
197	        uint64_t borrow = 0;
198	        uint64_t diff;
199	
200	        diff = a.limbs[0] - 0xFFFFFFFFFFFFFFFB;
201	        borrow = (diff > a.limbs[0]) ? 1 : 0;
202	        a.limbs[0] = diff;
203	
204	        diff = a.limbs[1] - 0xFFFFFFFFFFFFFFFF - borrow;
205	        borrow = (diff > a.limbs[1]) || (diff == a.limbs[1] && borrow);
206	        a.limbs[1] = diff;
207	
208	        a.limbs[2] -= borrow;
209	        a.limbs[2] &= mask; // Ensure top bits are zero
210	    }
211	    return a;
212	}
