364	poly1305_mac_fsm_t poly1305_mac_fsm(
365	    // Inputs
366	    stream(poly1305_key_uint_t) key,
367	    stream(axis128_t) data_in,
368	    uint1_t ready_for_auth_tag_out,
369	    u320_t from_compute,
370	    uint1_t from_compute_valid,
371	    uint1_t ready_for_to_compute
372	){
373	  poly1305_mac_fsm_t o;
374	  // Default not ready for incoming poly key
375	  o.ready_for_key = 0;
376	  // Default not ready for incoming data
377	  o.ready_for_data_in = 0;
378	  // Default not outputting an auth tag
379	  o.auth_tag.data = 0;
380	  o.auth_tag.valid = 0;
381	  // Default nothing into compute
382	  poly1305_mac_loop_body_in_t compute_null_inputs = {0};
383	  o.to_compute = compute_null_inputs;
384	  o.to_compute_valid = 0;
385	
386	  // The FSM
387	  static poly1305_state_t state;
388	  static uint1_t is_last_block;
389	  static u320_t a;
390	  static u320_t r;
391	  static u320_t s;
392	  if(state == IDLE){
393	    // Reset state
394	    is_last_block = 0; // Not the last block yet
395	    u320_t u320_null = {0};
396	    a = u320_null; // Initialize accumulator to 0
397	    r = u320_null; // Initialize r to 0
398	    s = u320_null; // Initialize s to 0
399	    // Wait for poly1305_key
400	    o.ready_for_key = 1;
401	    if(key.valid & o.ready_for_key){
402	      uint8_t poly1305_mac_data_key[POLY1305_KEY_SIZE];
403	      UINT_TO_BYTE_ARRAY(poly1305_mac_data_key, POLY1305_KEY_SIZE, key.data)
404	      // Key input
405	      u8_16_t r_bytes; // r part of the key
406	      u8_16_t s_bytes; // s part of the key
407	      // Split key into r and s 
408	      for(int32_t i=0; i<(POLY1305_KEY_SIZE/2); i+=1){
409	        r_bytes.bytes[i] = poly1305_mac_data_key[i];
410	        s_bytes.bytes[i] = poly1305_mac_data_key[i+16];
411	      }
412	      // Clamp r according to the spec
413	      r_bytes = clamp(r_bytes);
414	      // Convert r and s to u320_t and save in regs
415	      r = bytes_to_uint320(r_bytes.bytes);
416	      s = bytes_to_uint320(s_bytes.bytes);
417	      // Then start per block iterations
418	      state = START_ITER; 
419	    }
420	  }else if(state == FINISH_ITER){
421	    // Wait for 'a' data out of compute
422	    if(from_compute_valid){
423	      a = from_compute;
424	      // print 'a' every block
425	      //print_u320(a);
426	      // if last block do final step
427	      if(is_last_block){
428	        state = A_PLUS_S;
429	      }else{
430	        // More blocks using 'a' next
431	        state = START_ITER;
432	      }
433	    }
434	  }else if(state == A_PLUS_S){
435	    // a += s
436	    a = uint320_add(a, s);
437	    // Output a next
438	    state = OUTPUT_AUTH_TAG;
439	  }else if(state == OUTPUT_AUTH_TAG){
440	    // First 16 bytes of 'a' are the output  
441	    u320_t_bytes_t a_bytes = u320_t_to_bytes(a);
442	    uint8_t auth_tag[POLY1305_AUTH_TAG_SIZE];
443	    ARRAY_COPY(auth_tag, a_bytes.data, POLY1305_AUTH_TAG_SIZE)
444	    o.auth_tag.data = poly1305_auth_tag_uint_from_bytes(auth_tag);
445	    o.auth_tag.valid = 1;
446	    if(o.auth_tag.valid & ready_for_auth_tag_out){
447	      state = IDLE;
448	    }
449	  }
450	  // Same cycle transition from finish->start iter in one cycle
451	  // latency reduction = throughput increase in this case...
452	  if(state == START_ITER){
453	    // Ready to take an input data block
454	    o.ready_for_data_in = ready_for_to_compute;
455	    // Put 'a' and data block into compute
456	    o.to_compute.block_bytes = data_in.data.tdata;
457	    o.to_compute.a = a;
458	    o.to_compute.r = r;
459	    o.to_compute_valid = data_in.valid & o.ready_for_data_in;
460	    // Record if this is the last block
461	    is_last_block = data_in.data.tlast;
462	    // And then wait for the output once input into compute happens
463	    if(o.to_compute_valid & o.ready_for_data_in){
464	      state = FINISH_ITER;
465	    }
466	  }
467	  return o;
468	}
